package com.rescuefarm.service.engagement;
import com.rescuefarm.domain.enums.NotificationType;
public final class NotificationDeepLinkService{public String build(NotificationType type,String referenceId){String id=referenceId==null?"":referenceId.trim();if(id.isEmpty())return "rescuefarm://notifications";if(type==NotificationType.ORDER)return "rescuefarm://orders/"+id;if(type==NotificationType.CAMPAIGN)return "rescuefarm://campaigns/"+id;if(type==NotificationType.PROMOTION)return "rescuefarm://products/"+id;if(type==NotificationType.MODERATION)return "rescuefarm://notifications";return "rescuefarm://notifications";}}
